function placeOrder(inventory, order) {
  const seen = new Set();
  const next = { ...inventory };
  let totalCents = 0;
  for (const item of order.items) {
    if (seen.has(item.id)) {
      return { ok: false, error: "duplicate-item", inventory: { ...inventory } };
    }
    seen.add(item.id);
    if (!Object.prototype.hasOwnProperty.call(inventory, item.id)) {
      return { ok: false, error: "unknown-item", inventory: { ...inventory } };
    }
    if (!Number.isInteger(item.quantity) || item.quantity < 1) {
      return { ok: false, error: "invalid-quantity", inventory: { ...inventory } };
    }
    if (next[item.id] < item.quantity) {
      return { ok: false, error: "insufficient-stock", inventory: { ...inventory } };
    }
    next[item.id] -= item.quantity;
    totalCents += item.unitCents * item.quantity;
  }
  return { ok: true, inventory: next, totalCents: totalCents };
}
